-- Migration 049: SEO description drafts for the top-20 non-wallpaper
-- categories (marketing audit 2026-09: 166/176 active categories had no
-- copy; storefront renders categories.description on the category page and
-- feeds it into the meta description — app/lib/category-description.ts,
-- app/lib/seo.ts). The 10 wallpaper categories already carry texts from
-- data/category-seo-texts.sql and are NOT touched here.
--
-- Format mirrors the wallpaper seed (plain factual Ukrainian prose, no
-- marketing claims, no invented brand/warranty facts; apostrophes written
-- as ’ so no SQL-quote escaping is needed). The same texts are appended to
-- data/category-seo-texts.sql as UPDATEs — tests/category-seo-faq.test.ts
-- pins the seed/migration consistency.
--
-- Idempotent: re-running rewrites the same values. ВЛАДЕЛЕЦЬ ПРАВИТЬ ТЕКСТИ
-- В АДМІНЦІ — після ручних правок НЕ перезастосовувати цю міграцію.
--
-- VERIFY-PRE:
--   select count(*) from categories
--    where is_active and coalesce(description,'')='' and slug not like 'shpaleri%';
--   -- >0 (top-20 by active-product count all had no description)
-- VERIFY-POST:
--   select count(*) from categories
--    where coalesce(description,'')<>'' and slug not like 'shpaleri%';
--   -- 20

begin;

-- INSERT ... SELECT ... JOIN, не голый VALUES: Postgres проверяет NOT NULL
-- новой строки ДО разрешения конфликта, поэтому опущенный NOT NULL `name`
-- уронил бы весь statement с 23502, хотя каждый slug здесь конфликтует
-- (категории существуют). Джойн подставляет name существующей категории и
-- молча пропускает slug, которого вдруг не оказалось в БД.
insert into categories (slug, name, description)
select v.slug, c.name, v.description
from (values
('nozhi-1360', 'Кухонні ножі для щоденної роботи на кухні: шеф-ножі для нарізки м’яса та овочів, овочеві й хлібні ножі з зубчастим лезом, ножі для філе та невеликі моделі для чищення. Лезо найчастіше виготовляють з нержавіючої сталі, рукоятку — з пластику, дерева або композиту.

При виборі орієнтуйтеся на призначення: довге широке лезо зручно для нарізки великих шматків, коротке — для дрібної контрольованої роботи, зубчасте — для хліба та м’яких продуктів. Зверніть увагу на баланс: ніж має рівно лежати в руці, не переважаючи ні рукояткою, ні лезом. Твердіша сталь довше тримає заточку, але вимагає акуратнішого поводження.

Мийте ножі вручну та вчасно правте лезо мусатом або точилкою: тупе лезо зісковзує і небезпечніше гострого. Замовлення доставляємо по всій Україні, у Кривому Розі можна забрати товар самовивозом.'),
('tarilky-salatnyky-bliuda-1382', 'Столовий посуд для щоденних обідів і подачі: мілкі та глибокі тарілки, салатники різного об’єму, блюда для страв на компанію. Матеріали — фарфор, кераміка, фаянс і скло: від них залежать вигляд, вага та стійкість посуду до подряпин.

Обираючи посуд, зважайте на розмір родини та страви, які зазвичай подаєте: діаметр мілкої тарілки, глибина супової та об’єм салатника мають складати практичний набір на кожен день. Перевіряйте маркування на дні — воно підказує, чи можна посуд ставити в мікрохвильову піч і мити в посудомийній машині.

Кераміку та скло бережіть від різких перепадів температури, щоб не допустити тріщин. Доставка — по всій Україні, у Кривому Розі доступний самовивіз.'),
('skovoridky-ta-soteinyky-1367', 'Сковородки для смаження, гасіння та гриля й сотейники з високими стінками, у яких зручно тушкувати овочі та готувати соуси. Матеріали й покриття різняться: антипригарне покриття, чавун, нержавіюча сталь, литий алюміній — кожен має свої особливості нагріву та догляду.

Обирайте діаметр під кількість порцій і розмір конфорки, а матеріал — під тип плити: для індукційної потрібне феромагнітне дно, зазвичай воно позначене маркуванням. Зверніть увагу на ручку: термостійка або знімна дозволяє ставити посуд у духовку, пластикова — обмежує такі рецепти.

Для антипригарного покриття використовуйте дерев’яні або силіконові лопатки: метал дряпає поверхню й скорочує строк служби посуду. Замовлення доставляємо по всій Україні, у Кривому Розі працює самовивіз.'),
('formy-dlia-vypikannia-1368', 'Форми для випікання пирогів, кексів, хліба та запіканок: металеві з антипригарним покриттям, роз’ємні, силіконові, скляні та керамічні. Від матеріалу залежить, як рівно пропікається тісто і як легко діставати готову випічку.

Розмір і об’єм форми підбирайте під рецепти, які печете найчастіше: у надто великій тісто розтікається тонким коржем, у надто малій — переливається через край. Роз’ємне кільце зручно для чизкейків і тістечок, силікон не потребує змащування, але перевіряйте на етикетці максимальну температуру використання.

Скляні та керамічні форми добре тримають тепло, тож страву можна подавати прямо в них, однак різкий перепад температур їм шкодить. Доставка по всій Україні, у Кривому Розі можна забрати замовлення самовивозом.'),
('kukhonni-aksesuary-1348', 'Дрібне кухонне приладдя, без якого важко обійтися: лопатки, ополоники, шумівки, черпаки, роздільні дошки, консервні ключі та контейнери для зберігання. Матеріали — силікон, дерево, пластик і нержавіюча сталь, часто в одному наборі на кухню.

Підбирайте аксесуари під задачі: силіконові лопатки не дряпають антипригарні покриття й витримують гаряче, дерев’яні приємні на дотик, але потребують ручного миття, сталеве приладдя служить довго. Звертайте увагу на ручки з петлею для підвісу та на те, чи можна мити приладдя в посудомийній машині.

Окремі дошки для сирого м’яса та готових продуктів — проста звичка, що зменшує змішування запахів і полегшує підтримання чистоти. Замовлення доставляємо по всій Україні, у Кривому Розі доступний самовивіз.'),
('kholodylnyky-490', 'Холодильники окремостоячі та для вбудованої кухні, однокомпресорні й двокомпресорні, з крапельним розморожуванням або системою No Frost, яка не потребує ручного відтавання. У каталозі є моделі різного об’єму — від компактних до широких двостулкових.

Корисний об’єм підбирайте за кількістю людей у домі, а габарити звіряйте з нішею кухонного гарнітура, залишаючи запас для вентиляції. Показники, на які варто зважати: клас енергоефективності (він впливає на рахунки за світло), рівень шуму, якщо кухня межує зі спальнею, та наявність зони свіжості для овочів і м’яса.

Перед замовленням звірте ширину дверних прорізів і ліфта, а після доставки дайте техніці постояти кілька годин перед увімкненням. Доставляємо по всій Україні, у Кривому Розі доступний самовивіз.'),
('kastruli-ta-kovshi-1363', 'Каструлі для супів, каш і заготовок та ковші з довгою ручкою для молока, соусів і невеликих порцій. Матеріали: нержавіюча сталь, емальований метал, алюміній і чавун — вони по-різному тримають тепло й вимагають різного догляду.

Об’єм каструлі підбирайте за розміром родини: у маленькій зручно готувати на двох, у великій — варити супи на кілька днів і робити заготовки. Для індукційної плити потрібне феромагнітне дно (зазвичай воно маркується), а багатошарне дно рівніше прогріває страви. Скляна кришка з паровідводом дозволяє стежити за готуванням, не піднімаючи її.

Емальовані каструлі бережіть від ударів: скол емалі виводить посуд із користування, а антипригарні стінки не чистіть абразивами. Доставка по всій Україні, у Кривому Розі можна забрати товар самовивозом.'),
('nabory-nozhiv-1359', 'Набори кухонних ножів у підставці, на магнітному тримачі або в кейсі: зазвичай до них входять шеф-ніж, овочевий і хлібний ножі, нерідко додані ножиці та мусат для правки леза. Це зручний старт для нової кухні та подарунок, що не потребує підбору окремих предметів.

Звертайте увагу не на кількість предметів, а на їхній реальний склад: три-чотири ножі, якими ви справді користуєтесь, практичніші за десяток рідко вживаних. Перевіряйте сталь лез, матеріал рукояток і наявність точилки чи мусата в комплекті, а також тип підставки — вона має стояти стабільно й легко чиститися.

Зберігайте ножі в підставці або на магнітній планці: у шухляді лезо тупиться швидше, а дістаючи ніж, легко порізатися. Замовлення доставляємо по всій Україні, у Кривому Розі працює самовивіз.'),
('elektrochainyky-1409', 'Електрочайники з корпусом із металу, пластику або скла: метал довше тримає тепло, скло дозволяє бачити рівень води, пластик легший і доступніший за ціною. Типовий об’єм — від 1 до 1,7 літрів, чого вистачає і на сім’ю, і на офіс.

Ключові функції, які варто перевірити: автоматичне вимкнення при закипанні, захист від увімкнення без води, знімний фільтр проти накипу та прозоре віконце з шкалою рівня води. Потужність визначає швидкість закипання — на ній зважайте, якщо чайником користуються часто й кілька людей поспіль.

Чайник простий в обслуговуванні: періодично видаляйте накип лимонною кислотою або спеціальним засобом і промивайте фільтр. Доставка по всій Україні, у Кривому Розі доступний самовивіз.'),
('pralni-mashyny-488', 'Пральні машини з фронтальним і вертикальним завантаженням: перші зручні тим, що верх машини можна використовувати або ховати під стільницю, другі не потребують місця для відкритих дверцят попереду. За глибиною розрізняють вузькі моделі для тісних ванних та повнорозмірні.

Завантаження підбирайте за об’ємом прання: для родини з кількох осіб зазвичай вистачає шести-восьми кілограмів, для одного користувача менше. Зважайте на швидкість віджиму, клас енергоефективності, рівень шуму та набір програм — делікатні, швидкі та режими для вовни чи дитячого одягу.

Плануйте місце встановлення заздалегідь: машина потребує підключення до води, каналізації та розетки, а на нерівній підлозі — регулювання ніжок. Доставляємо по всій Україні, у Кривому Розі можна забрати товар самовивозом.'),
('pylosmoky-akumuliatorni-ta-abo-robotyzovani-1247', 'Два формати бездротового прибирання: вертикальні акумуляторні пилосмоки для швидкого прибирання по дому та роботизовані, які самі об’їжджають кімнати за розкладом. Сміття збирається в циклонний контейнер або мішок, у багатьох моделях є вологе прибирання.

Для акумуляторних зважайте на час роботи від однієї зарядки та силу всмоктування, для роботів — на систему навігації, висоту корпусу (чи заїде під ліжко й шафу) і наявність зарядної бази. Тип щіток підбирайте під покриття: для килимів потрібна турбощітка, для ламінату та плитки — м’які насадки й вологе прибирання.

Фільтри та контейнер потрібно регулярно чистити: від цього залежить тяга пилососа і чистота повітря на виході. Замовлення доставляємо по всій Україні, у Кривому Розі доступний самовивіз.'),
('prasky-parovi-systemy-103', 'Праски та парові системи для догляду за одягом: звичайні парові праски, станції з окремим бойлером для великих об’ємів білизни та компактні моделі для подорожей. Матеріал підошви визначає ковзання та рівномірність нагріву.

Обирайте за об’ємом прання: для кількох речей на тиждень достатньо звичайної праски, для родини зі школярами зручніша парова станція з подачею пари від бойлера. Звертайте увагу на продуктивність подачі пари, наявність парового удару та вертикального відпарювання, а в бездротових моделях — на час роботи без шнура.

Накип — головна причина слабкої пари: використовуйте функцію самоочищення або спеціальні засоби, щоб пароутворення залишалося стабільним. Доставка по всій Україні, у Кривому Розі працює самовивіз.'),
('mashynky-dlia-stryzhky-1425', 'Машинки для стрижки волосся для домашнього догляду та професійного використання: мережеві, акумуляторні та комбіновані моделі, які працюють і від розетки, і від батареї. Лезо буває сталевим, з керамічними вставками або додатковим покриттям — від цього залежать нагрів і плавність ходу.

Насадки-гребінці визначають діапазон довжин стрижки, тож звірте їхній набір із тим, які стрижки ви робите. Для акумуляторних моделей зважайте на час автономної роботи, для дитячих стрижок — на рівень шуму та можливість промивати насадки під водою.

Після стрижки очищуйте лезо від волосся та періодично змащуйте його: машина працюватиме тихіше й прослужить довше. Замовлення доставляємо по всій Україні, у Кривому Розі доступний самовивіз.'),
('chashky-1391', 'Чашки та кружки для чаю, кави й какао: керамічні, порцелянові, скляні та моделі з подвійними стінками, які довго тримають температуру напою й не обпікають руки. Об’єми різняться від компактних кавових чашок до великих кружок.

Підбирайте об’єм під напій: кава зручна в маленькій чашці, чай і какао — у великій кружці. Перевіряйте маркування: чи можна чашку гріти в мікрохвильовій печі та мити в посудомийній машині, і наскільки стійкий декор до миття.

Вироби зі скла з подвійними стінками зазвичай не призначені для мікрохвильовки — це вказано в маркуванні, а тонку порцеляну мийте акуратно. Доставка по всій Україні, у Кривому Розі можна забрати замовлення самовивозом.'),
('stolovi-prybory-1387', 'Столові прилади з нержавіючої сталі: ложки, виделки та ножі поштучно і в наборах на родину. Сталь буває різних марок: з додаванням нікелю (маркування 18/10) вона блищить і довше виглядає як нова, без нікелю — простіший щоденний варіант.

Обираючи прилади, зважте на вагу і товщину металу: тонкі легко гнуться при різанні, а щільні приємніші в руці та довше зберігають вигляд. Набори зручні єдиним дизайном, але звірте склад: іноді потрібні лише основні ложки й виделки, а десертні прилади докупуються окремо.

Прилади з нержавіючої сталі можна мити в посудомийній машині; щоб уникнути плям, не залишайте їх надовго брудними після їжі. Замовлення доставляємо по всій Україні, у Кривому Розі працює самовивіз.'),
('feny-1428', 'Фени для швидкого сушіння та укладання волосся: побутові моделі для дому, компактні для подорожей і потужніші для складних укладок. У комплекті бувають насадки — концентратор для спрямованого потоку повітря та дифузор для кучерів і об’єму.

Потужність визначає швидкість сушіння, але для тонкого й пошкодженого волосся важливіші знижені температурні режими: звертайте увагу на кількість режимів нагріву та швидкостей. Корисні дрібниці — кнопка холодного повітря для фіксації укладки, іонізація проти електризації та кільце для підвісу.

Не перегрівайте волосся: починайте з нижчої температури й підвищуйте за потреби, а насадки періодично очищуйте від волосся та пилу. Доставка по всій Україні, у Кривому Розі доступний самовивіз.'),
('vytiazhky-1215', 'Кухонні витяжки для очищення повітря від пари, жиру та запахів: плоскі підвісні, вбудовані в шафу, купольні та острівні моделі. Вони працюють у двох режимах — відведення повітря у вентиляцію або рециркуляція з очищенням фільтрами.

Продуктивність підбирайте під площу кухні: слабка витяжка не встигатиме прибирати запахи, а надмірно потужна буде шуміти. Для рециркуляційних моделей зважайте на доступність замінних вугільних фільтрів, а рівень шуму перевіряйте, якщо кухня об’єднана з вітальнею.

Металеві жирові фільтри мийні: їх достатньо регулярно промивати, щоб тримати тягу на стабільному рівні. Замовлення доставляємо по всій Україні, у Кривому Розі можна забрати товар самовивозом.'),
('poverkhni-197', 'Варильні поверхні для вбудованої установки в стільницю: газові з ґратами, електричні та індукційні зі склокерамічною панеллю. Від типу залежить і посуд: для індукції потрібне феромагнітне дно, для газу та звичайної електрики підходить будь-який.

Заздалегідь звірте розмір і форму вирізу в стільниці: габарити поверхонь і кількість конфорок різняться. Керування буває поворотним та сенсорним; індукційні моделі гріють швидше й залишають менше тепла на кухні, але вимагають відповідного посуду.

Склокерамічну панель протирайте м’якою губкою без абразивних засобів, щоб не подряпати поверхню, а газові ґрати зручніше мити у знімному вигляді. Доставка по всій Україні, у Кривому Розі працює самовивіз.'),
('elektroshchitky-zubni-118', 'Електричні зубні щітки для щоденного догляду: звукові з високочастотними коливаннями та обертові з круглою голівкою. Моделі розрізняються за режимами чищення, потужністю та комплектом насадок — для дорослих і дитячих.

Корисні функції, на які варто зважати: вбудований таймер із поділом на ділянки рота, датчик надмірного тиску для чутливих ясен та режими — звичайний, чутливий, для відбілювання. Перед покупкою перевірте доступність змінних насадок: їх оновлюють регулярно, у міру зношення щетинок.

Заряду більшості моделей вистачає на кілька днів щоденних чисток, тож у поїздці можна обійтися без зарядного пристрою. Замовлення доставляємо по всій Україні, у Кривому Розі доступний самовивіз.'),
('blendery-1402', 'Блендери двох форматів: занурені для супів-пюре і соусів прямо в каструлі та стаціонарні з чашею для смузі, коктейлів і подрібнення льоду. Потужність і оберти визначають, наскільки гладкою буде консистенція та чи впорається прилад із твердими продуктами.

Для смузі з льодом і заморожених ягід обирайте потужніші моделі та чашу з щільного пластику або скла, для соусів і дитячого харчування вистачить компактного занурного блендера. Звертайте увагу на швидкості та імпульсний режим, знімні деталі, які можна мити в посудомийній машині, і на комплект насадок — віночок, подрібнювач.

Занурний блендер зручно зберігати в шухляді, стаціонарний потребує місця на стільниці: звірте габарити перед замовленням. Доставляємо по всій Україні, у Кривому Розі працює самовивіз.')
) as v(slug, description)
join categories c on c.slug = v.slug
on conflict (slug) do update set description = excluded.description;

commit;
